-- 政策通分类示例文章（15个，type='policy'）
INSERT INTO `article` 
  (`id`, `title`, `summary`, `content`, `category`, `type`, `date`, `is_premium`, `read_time`, `view_count`, `favorite_count`, `likes`, `share_count`, `is_sticky`, `created_at`, `updated_at`)
VALUES
  (UUID(), '2024年项目申报指南发布', '本年度重点支持科技创新、产业升级等领域项目申报，最高资助500万元。', '<h2>申报重点</h2><p>本年度项目申报重点支持以下领域：</p><ul><li>科技创新与研发</li><li>产业转型升级</li><li>绿色低碳发展</li><li>数字经济建设</li></ul><h2>资助标准</h2><p>根据项目类型和规模，提供10万至500万元不等的资金支持。</p>', '项目申报', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '互联网经济发展新政策出台', '支持平台经济健康发展，优化数字经济营商环境，推动产业数字化转型。', '<h2>政策背景</h2><p>为促进互联网经济健康有序发展，政府出台系列支持政策。</p><h2>主要内容</h2><ul><li>优化平台企业监管</li><li>支持数字技术创新</li><li>完善数据安全保护</li><li>推动产业数字化</li></ul><p>预计将带动相关产业投资超过1000亿元。</p>', '互联网经济', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '智能制造产业扶持政策解读', '重点支持工业互联网、智能工厂建设，推动制造业高质量发展。', '<h2>政策要点</h2><p>本次政策聚焦智能制造核心领域：</p><ul><li>工业互联网平台建设</li><li>智能工厂改造升级</li><li>关键技术攻关</li><li>人才培养引进</li></ul><h2>支持措施</h2><p>提供资金补贴、税收优惠、用地保障等全方位支持。</p>', '智能制造', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '金融财税优惠政策汇总', '最新税收减免、融资支持政策详解，助力企业降本增效。', '<h2>税收优惠</h2><ul><li>研发费用加计扣除75%</li><li>高新技术企业所得税15%</li><li>小微企业增值税减免</li></ul><h2>融资支持</h2><p>提供低息贷款、融资担保、上市奖励等多种金融支持。</p>', '金融财税', 'policy', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '福州市科技创新扶持政策', '福州市出台科技创新十条，全力打造创新型城市。', '<h2>政策亮点</h2><p>福州市科技创新扶持政策包括：</p><ul><li>研发投入补助最高500万</li><li>高层次人才奖励100万</li><li>科技成果转化奖励</li><li>创新平台建设支持</li></ul>', '福州政策', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '厦门市产业发展专项资金管理办法', '厦门市设立50亿产业发展基金，支持重点产业发展。', '<h2>资金用途</h2><p>专项资金主要用于：</p><ul><li>重点产业项目引进</li><li>产业链关键环节补强</li><li>创新平台建设</li><li>产业人才引进</li></ul><h2>申报条件</h2><p>符合厦门市产业发展规划的企业和项目均可申报。</p>', '厦门政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '莆田市制造业转型升级政策', '莆田市推动传统制造业向智能化、绿色化转型。', '<h2>转型方向</h2><ul><li>智能制造升级</li><li>绿色低碳改造</li><li>品牌建设提升</li><li>产业链协同发展</li></ul><p>对符合条件的项目给予最高300万元补助。</p>', '莆田政策', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '三明市绿色产业发展规划', '三明市打造全国绿色发展示范区，推动生态产业化。', '<h2>发展重点</h2><p>三明市绿色产业发展聚焦：</p><ul><li>林业经济</li><li>生物医药</li><li>清洁能源</li><li>生态旅游</li></ul><h2>政策支持</h2><p>提供用地、资金、人才等全方位保障。</p>', '三明政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '泉州市民营经济发展新政', '泉州市出台民营经济30条，激发市场主体活力。', '<h2>政策内容</h2><ul><li>降低企业运营成本</li><li>优化营商环境</li><li>加大金融支持</li><li>保护企业家权益</li></ul><p>预计惠及10万家民营企业。</p>', '泉州政策', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '漳州市现代农业发展政策', '漳州市推动农业现代化，打造特色农业品牌。', '<h2>发展目标</h2><p>建设现代农业产业园，培育农业龙头企业。</p><h2>支持措施</h2><ul><li>农业基础设施建设</li><li>农产品品牌培育</li><li>农业科技创新</li><li>农村电商发展</li></ul>', '漳州政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '南平市生态旅游产业政策', '南平市发挥生态优势，打造全域旅游示范区。', '<h2>产业布局</h2><p>构建一核两带三区旅游发展格局。</p><ul><li>武夷山核心景区</li><li>闽江生态旅游带</li><li>乡村旅游示范区</li></ul><p>对旅游项目给予最高500万元支持。</p>', '南平政策', 'policy', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '龙岩市红色文化产业发展规划', '龙岩市传承红色基因，发展红色文化旅游产业。', '<h2>发展思路</h2><ul><li>红色旅游精品线路</li><li>革命文物保护利用</li><li>红色文化创意产业</li><li>研学旅行基地建设</li></ul><h2>政策保障</h2><p>设立专项资金，支持红色文化项目建设。</p>', '龙岩政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '宁德市新能源产业集群政策', '宁德市打造世界级新能源产业基地，引领产业发展。', '<h2>产业优势</h2><p>宁德已形成完整的新能源产业链：</p><ul><li>锂电池制造</li><li>新能源汽车</li><li>储能系统</li><li>关键材料</li></ul><p>对重大项目给予一事一议支持。</p>', '宁德政策', 'policy', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '平潭综合实验区开放政策', '平潭实施更加开放的政策，打造两岸融合发展示范区。', '<h2>政策特色</h2><ul><li>两岸贸易便利化</li><li>台胞创业就业支持</li><li>跨境电商发展</li><li>国际旅游岛建设</li></ul><h2>优惠措施</h2><p>享受自贸区、综合实验区双重政策叠加。</p>', '平潭政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '文旅产业融合发展政策', '推动文化和旅游深度融合，培育新型文旅业态。', '<h2>融合方向</h2><p>文旅产业融合发展重点：</p><ul><li>文化创意旅游</li><li>数字文旅体验</li><li>非遗活化利用</li><li>夜间经济发展</li></ul><h2>支持政策</h2><p>对优质文旅项目给予资金、用地、人才等支持。</p>', '文旅政策', 'policy', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW());

-- 产业情报·免费分类示例文章（22个，type='industry'）
INSERT INTO `article` 
  (`id`, `title`, `summary`, `content`, `category`, `type`, `date`, `is_premium`, `read_time`, `view_count`, `favorite_count`, `likes`, `share_count`, `is_sticky`, `created_at`, `updated_at`)
VALUES
  (UUID(), '氟化工产业链深度分析', '我国氟化工产业规模持续扩大，高端产品国产化率不断提升。', '<h2>产业现状</h2><p>氟化工是化工行业的重要分支，广泛应用于制冷剂、含氟聚合物、含氟精细化学品、电子化学品等领域。</p><h2>发展趋势</h2><p>向高端化、绿色化、精细化方向发展，第四代制冷剂成为新热点。</p>', '氟化工', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '石墨烯应用领域突破进展', '石墨烯在储能、散热、复合材料等领域实现商业化应用。', '<h2>技术突破</h2><p>石墨烯制备技术不断成熟，CVD法规模化生产、氧化还原法成本降低、液相剥离技术优化。</p><h2>应用场景</h2><p>锂电池导电剂、散热膜、防腐涂料等领域需求快速增长。</p>', '石墨烯', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '轻合金材料市场需求分析', '铝合金、镁合金在汽车轻量化领域需求旺盛。', '<h2>市场规模</h2><p>全球轻合金市场规模超过2000亿美元，年增长率8%。</p><h2>应用领域</h2><p>汽车轻量化、航空航天、电子产品、轨道交通等。新能源汽车发展带动轻合金需求快速增长。</p>', '轻合金', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '竹产业绿色发展新模式', '竹材加工向高值化、精深化方向发展，竹产业链不断延伸。', '<h2>产业优势</h2><p>竹子生长快、可再生，是理想的绿色材料。</p><h2>应用拓展</h2><p>竹建材、竹纤维制品、竹炭产品、竹笋食品等。竹产业产值有望突破3000亿元。</p>', '竹产业', 'industry', CURDATE(), 0, 3, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '绿色再制造产业政策机遇', '再制造产业迎来政策红利期，市场空间广阔。', '<h2>政策支持</h2><p>国家大力支持再制造产业发展，提供税收优惠政策、绿色采购支持、技术标准完善、示范基地建设等。</p><h2>重点领域</h2><p>工程机械、汽车零部件、机电产品再制造。</p>', '绿色再制造', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '生物医药产业创新发展', '生物医药成为战略性新兴产业，创新药研发投入持续增加。', '<h2>产业现状</h2><p>我国生物医药产业规模超过4万亿元。</p><h2>创新方向</h2><p>抗体药物、基因治疗、细胞治疗、mRNA疫苗等。创新药、高端医疗器械、CRO/CDMO服务成为投资热点。</p>', '生物医药', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '高端纺织产业转型升级', '纺织产业向智能化、功能化、时尚化方向发展。', '<h2>转型方向</h2><p>智能制造应用、功能性面料开发、品牌建设提升、绿色生产改造。</p><h2>市场机遇</h2><p>运动服饰、户外装备、医用纺织品需求增长。</p>', '高端纺织', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '稀土产业战略价值凸显', '稀土作为战略资源，在高科技领域应用不可替代。', '<h2>资源优势</h2><p>我国稀土储量和产量均居世界首位。</p><h2>应用领域</h2><p>永磁材料、催化材料、发光材料、储氢材料等。向高端应用、绿色开采、循环利用方向发展。</p>', '稀土产业', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '林产业高质量发展路径', '林产业向生态化、精深化、多元化方向转型。', '<h2>产业链条</h2><p>木材加工、林下经济、森林旅游、林业碳汇等。</p><h2>发展机遇</h2><p>碳达峰碳中和目标下，林业碳汇价值凸显。</p>', '林产业', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '绿色铸锻技术创新应用', '铸锻行业向绿色化、智能化、精密化方向发展。', '<h2>技术进步</h2><p>精密铸造技术、数字化锻造、节能环保工艺、智能检测系统等技术突破。</p><h2>应用领域</h2><p>汽车、航空、能源装备等高端制造领域。</p>', '绿色铸锻', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '新能源汽车产业链全景', '新能源汽车渗透率快速提升，产业链投资机会涌现。', '<h2>市场规模</h2><p>2024年新能源汽车销量预计突破1000万辆。</p><h2>产业链条</h2><p>动力电池、电驱系统、智能座舱、自动驾驶等。固态电池、800V高压平台、智能驾驶芯片成为投资热点。</p>', '新能源汽车', 'industry', CURDATE(), 0, 6, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '锂电新能源产业深度报告', '锂电池技术持续进步，储能市场成为新增长点。', '<h2>技术路线</h2><p>高镍三元电池、磷酸铁锂电池、固态电池、钠离子电池等技术发展。</p><h2>应用拓展</h2><p>从动力电池向储能、两轮车、工具等领域延伸。</p>', '锂电新能源', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '不锈钢新材料应用前景', '不锈钢向高端化、专用化方向发展，应用领域不断拓展。', '<h2>产品升级</h2><p>超级不锈钢、双相不锈钢、节镍型不锈钢、特殊用途不锈钢等新材料发展。</p><h2>市场需求</h2><p>新能源、海洋工程、高端装备等领域需求增长。</p>', '不锈钢新材料', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '铜材料产业链分析', '铜材料在电力、电子、新能源领域需求稳定增长。', '<h2>产业现状</h2><p>我国铜材产量居世界首位，深加工能力强。</p><h2>应用领域</h2><p>电力电缆、电子元器件、新能源汽车、5G通信等。向高精度、高性能、环保型方向发展。</p>', '铜材料', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '海洋渔业现代化发展', '海洋渔业向智能化、生态化、品牌化方向转型。', '<h2>发展模式</h2><p>深远海养殖、智慧渔业、水产品加工、休闲渔业等。</p><h2>技术创新</h2><p>深海网箱、循环水养殖、物联网监测等技术应用。</p>', '海洋渔业', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '食用菌产业规模化发展', '食用菌产业向标准化、工厂化、品牌化方向发展。', '<h2>产业规模</h2><p>我国食用菌产量超过4000万吨，产值超过3000亿元。</p><h2>发展方向</h2><p>工厂化生产、珍稀品种培育、精深加工、品牌建设等。健康食品需求带动食用菌消费增长。</p>', '食用菌', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '中药材产业振兴机遇', '中药材种植向规范化、标准化、生态化方向发展。', '<h2>政策支持</h2><p>国家大力支持中药材产业发展，道地药材保护、种植基地建设、质量标准提升、品牌培育推广等。</p><h2>市场需求</h2><p>中医药市场规模持续扩大，中药材需求旺盛。</p>', '中药材', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '茶产业品牌化发展路径', '茶产业向品牌化、标准化、国际化方向转型。', '<h2>产业优势</h2><p>我国是世界最大的茶叶生产国和消费国。</p><h2>发展方向</h2><p>品牌建设、标准化生产、茶旅融合、国际市场拓展等。新式茶饮、茶文化体验、茶叶深加工等新业态兴起。</p>', '茶产业', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '机械产业智能化转型', '机械产业向数字化、智能化、服务化方向发展。', '<h2>转型路径</h2><p>数字化设计、智能制造、远程运维、产业互联网等。</p><h2>重点领域</h2><p>工程机械、农业机械、专用设备等领域加速转型。</p>', '机械产业专题', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '超精密机床技术突破', '超精密机床向高精度、高效率、智能化方向发展。', '<h2>技术进展</h2><p>纳米级加工精度、五轴联动技术、智能补偿系统、在线检测技术等关键技术突破。</p><h2>应用领域</h2><p>航空航天、半导体、医疗器械等高端制造领域。</p>', '超精密机床', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '专用车市场需求分析', '专用车向电动化、智能化、专业化方向发展。', '<h2>市场规模</h2><p>专用车市场保持稳定增长，细分领域机会多。</p><h2>产品类型</h2><p>物流配送车、环卫作业车、工程作业车、应急救援车等。新能源专用车、智能作业车成为新热点。</p>', '专用车', 'industry', CURDATE(), 0, 4, 0, 0, 0, 0, 0, NOW(), NOW()),
  
  (UUID(), '无人机产业应用拓展', '无人机在农业、物流、测绘等领域应用快速增长。', '<h2>应用场景</h2><p>农业植保、物流配送、测绘勘探、应急救援、影视航拍等领域不断拓展。</p><h2>技术发展</h2><p>长航时、大载重、智能避障等技术持续进步。</p>', '无人机', 'industry', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW());

