VALUES
  (UUID(), '科技资讯月报2024年5月刊', '本期聚焦人工智能、新能源、生物医药等前沿科技领域最新动态。', '<h2>本期导读</h2><ul><li>AI大模型技术突破</li><li>固态电池商业化进展</li><li>基因编辑新应用</li><li>量子计算最新成果</li></ul><h2>重点关注</h2><p>人工智能技术在各行业的深度应用，新能源技术路线的演进方向，生物医药创新药物研发进展。</p>', '科技资讯月报', 'publication', CURDATE(), 0, 6, 0, 0, 0, 0, 0, NOW(), NOW()),
  (UUID(), '科创快讯第128期', '本期快讯汇总本周科技创新领域重要新闻和政策动态。', '<h2>政策要闻</h2><p>科技部发布新一轮科技创新支持政策，重点支持基础研究和关键核心技术攻关。</p><h2>行业动态</h2><ul><li>多家科技企业发布创新产品</li><li>重大科研项目取得突破</li><li>产学研合作深入推进</li></ul><h2>投融资</h2><p>本周科技领域投融资活跃，人工智能、新能源等赛道受到资本青睐。</p>', '科创快讯', 'publication', CURDATE(), 0, 5, 0, 0, 0, 0, 0, NOW(), NOW());
